 if(state.salesSort==='oldest')filtered.sort((a,b)=>new Date(a.date||a.createdAt||a.created_date)-new Date(b.date||b.createdAt||b.created_date));else if(state.salesSort==='amount')filtered.sort((a,b)=>Number(b.sales_total||b.total_amount||b.total||0)-Number(a.sales_total||a.total_amount||a.total||0));else filtered.sort((a,b)=>new Date(b.date||b.createdAt||b.created_date)-new Date(a.date||a.createdAt||a.created_date));
