async function loadStockJournal(){
 const fetchPage=async(page)=>{try{return await get('stocklogs',{limit:100,page});}catch(error){if(page===1)return get('stock-logs',{limit:100,page});throw error;}};
 const first=await fetchPage(1),payload=first?.data&&typeof first.data==='object'?first.data:first;
 const rows=rowsOf(first),totalPages=Math.max(1,Number(payload?.total_pages??first?.total_pages??first?.data?.data?.total_pages??1)||1);
 if(totalPages>1){for(let page=2;page<=totalPages;page+=5){const batch=await Promise.all(Array.from({length:Math.min(5,totalPages-page+1)},(_,i)=>fetchPage(page+i)));for(const response of batch)rows.push(...rowsOf(response));}}
 return {data:{list:rows,total:payload?.total??first?.total??rows.length,total_pages:totalPages}};
}
