async function loadCustomerDebtCache(force=false){
 if(force){customerDebtCache=null;customerDebtCachePromise=null;}
 if(customerDebtCache instanceof Map)return customerDebtCache;
 if(!customerDebtCachePromise){
  customerDebtCachePromise=get('credit/outstanding').then(response=>{
   const map=new Map();
   for(const row of rowsOf(response)){
    const id=customerIdOf(row.customer_id??row.customerId??row._id);
    if(!id)continue;
    const due=Math.max(0,Number(row.due??row.outstanding??row.balance??row.payment_pending??0)||0);
    map.set(id,(map.get(id)||0)+due);
   }
   customerDebtCache=map;
   return map;
  }).catch(error=>{customerDebtCachePromise=null;throw error;});
 }
 return customerDebtCachePromise;
}
