 const period=e.target.closest('[data-history-period]');
 if(period){state.salesPeriod=period.dataset.historyPeriod;state.salesDay='';await render();return;}
 const month=e.target.closest('[data-history-month]');
 if(month){const currentMonth=state.salesMonth||new Date().toISOString().slice(0,7),d=new Date(currentMonth+'-01T12:00:00');d.setMonth(d.getMonth()+Number(month.dataset.historyMonth));state.salesMonth=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');state.salesDay='';await render();return;}
 const day=e.target.closest('[data-history-day]');
