root.addEventListener('click',async e=>{const day=e.target.closest('[data-closure-day]');if(day){e.preventDefault();state.closureDate=day.dataset.closureDay;await render();return;}const month=e.target.closest('[data-closure-month]');if(month){e.preventDefault();const currentMonth=state.closureMonth||state.closureDate||new Date().toISOString().slice(0,10),d=new Date(currentMonth.slice(0,7)+'-01T12:00:00');d.setMonth(d.getMonth()+Number(month.dataset.closureMonth));state.closureMonth=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');await render();return;}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='print-z-report'){e.preventDefault();const paper=document.querySelector('.thermal-paper');if(!paper)throw new Error('Aucun ticket de clôture à imprimer.');const reportHtml='<!doctype html><html><head><title>SamarinaPOS · Z-Report</title><style>@page{size:80mm auto;margin:2mm}body{margin:0;font-family:monospace}.thermal-paper{width:76mm;margin:0;padding:2mm;color:#111}.thermal-line{display:flex;justify-content:space-between;gap:6px;padding:3px 0;border-bottom:1px dashed #ddd;font-size:10px}.thermal-line span{max-width:65%;overflow-wrap:anywhere}.thermal-line b{white-space:nowrap}.thermal-section-title{margin:10px 0 3px;padding:5px 0 3px;border-top:1px dashed #64748b;font-size:10px;font-weight:800;text-transform:uppercase}.thermal-cash-total{margin-top:7px;padding:8px 4px!important;border-top:2px solid #111!important;border-bottom:2px solid #111!important;font-size:12px!important;font-weight:900!important;background:#f1f5f9}</style></head><body>'+paper.outerHTML+'</body></html>';await printHtmlDocument(reportHtml,{pageSize:'80mm',printerName:document.querySelector('#printer-form [name="printer"]')?.value||'',silent:true},'Rapport de caisse imprimé avec succès.');return;}},true);
async function boot(){const savedVendor=localStorage.getItem('samarinapos-active-vendor');if(savedVendor){try{state.activeVendor=JSON.parse(savedVendor);}catch(_){state.activeVendor=null;}}const ok=await checkSession();if(ok){state.view=location.hash.slice(1)||'caisse';if(!canAccessRoute(state.user,state.view,state.view==='clients'?1:0)){state.view='caisse';state.tab=0;location.hash='caisse';}else if(!isAdminUser()&&state.view==='clients')state.tab=1;void searchCustomers('').catch(()=>{});startMobileBasketSync();await render();}else login();}
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(modules.some(x=>x.id===id)){const targetTab=!isAdminUser()&&id==='clients'?1:0;if(!canAccessRoute(state.user,id,targetTab)){state.view='caisse';state.tab=0;location.hash='caisse';render();return;}if(id===state.view)return;cleanupNavigationOverlays();state.view=id;state.tab=targetTab;render();}});
